:root{
  --canvas:#0a0a0c; --panel:#101013; --panel2:#141419; --rule:#2a2620; --rule2:#3a332a;
  --ink:#f2ede6; --muted:#9a938a; --faint:#6b655c;
  --copper:#d29a5b; --gold:#e8c07a; --gold-dim:#8a6f3f;
  --green:#3ecf8e; --red:#f26d5f;
  --serif:Georgia,'Times New Roman',serif;
  --mono:ui-monospace,'SF Mono',Menlo,Consolas,monospace;
}
*{box-sizing:border-box}
html{background:var(--canvas)}
body{margin:0 auto;max-width:1320px;padding:28px 22px 40px;background:var(--canvas);color:var(--ink);
  font-family:var(--mono);font-size:14px;line-height:1.55}
a{color:var(--gold)}
h1,h2,h3{font-family:var(--serif);font-weight:400;margin:0}
h1{font-size:52px;line-height:1.05;letter-spacing:.01em}
h2{font-size:30px;margin-bottom:14px}
h3{font-size:19px;color:var(--copper);margin:18px 0 8px;text-transform:uppercase;letter-spacing:.14em;font-size:13px;font-family:var(--mono);font-weight:700}
p{margin:0 0 12px}
.masthead{border-bottom:3px double var(--rule2);padding-bottom:18px;margin-bottom:0}
.kicker{color:var(--copper);text-transform:uppercase;letter-spacing:.22em;font-size:11px;margin-bottom:14px}
.sub{font-family:var(--serif);font-size:18px;color:var(--muted);max-width:760px;margin-top:12px;line-height:1.5}
.proof-line{font-size:13px;color:var(--muted);margin:12px 0 0}
.proof-line b{color:var(--gold);font-weight:700}
.ledger-line{display:flex;flex-wrap:wrap;gap:0;margin:18px 0 0;padding:0;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule)}
.ledger-line div{padding:10px 22px 10px 0;margin-right:22px;border-right:1px solid var(--rule)}
.ledger-line div:last-child{border-right:0}
.ledger-line dt{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.16em}
.ledger-line dd{margin:2px 0 0;font-size:20px;color:var(--gold)}
.tabs{display:flex;gap:2px;margin:0 0 20px;border-bottom:1px solid var(--rule)}
.tab{background:none;border:0;border-bottom:2px solid transparent;color:var(--muted);font-family:var(--mono);font-size:13px;
  text-transform:uppercase;letter-spacing:.14em;padding:12px 18px 10px;cursor:pointer}
.tab:hover{color:var(--ink)}
.tab.active{color:var(--gold);border-bottom-color:var(--gold)}
.view{margin-top:6px}
.lede{font-family:var(--serif);font-size:17px;color:var(--muted);max-width:780px}
.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin-bottom:10px}
.toolbar label{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.14em}
.search input,.select select{background:var(--panel);border:1px solid var(--rule2);color:var(--ink);
  font-family:var(--mono);font-size:13px;padding:8px 10px;border-radius:2px;outline:none}
.search input{width:260px}
.search input:focus,.select select:focus{border-color:var(--copper)}
.chips{display:flex;gap:6px}
.chip{background:var(--panel);border:1px solid var(--rule2);color:var(--muted);font-family:var(--mono);
  font-size:12px;letter-spacing:.08em;padding:8px 14px;border-radius:2px;cursor:pointer}
.chip:hover{color:var(--ink);border-color:var(--copper)}
.chip.active{background:var(--gold);border-color:var(--gold);color:#14100a;font-weight:700}
.count{color:var(--faint);font-size:12px;margin:0 0 8px}
.table-wrap{overflow-x:auto;border:1px solid var(--rule);background:var(--panel)}
table{border-collapse:collapse;width:100%;font-size:13px}
th{color:var(--copper);font-size:11px;text-transform:uppercase;letter-spacing:.12em;text-align:left;
  padding:8px 10px;border-bottom:1px solid var(--rule2);white-space:nowrap}
td{padding:8px 10px;border-bottom:1px solid var(--rule);vertical-align:middle}
tbody tr{cursor:pointer}
tbody tr:hover{background:var(--panel2)}
tbody tr:last-child td{border-bottom:0}
.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.rank{font-family:var(--serif);font-size:22px;color:var(--gold);width:44px}
.pname{font-family:var(--serif);font-size:16px;color:var(--ink)}
td small{display:block;font-family:var(--mono);font-size:11px;color:var(--faint)}
.cat{color:var(--muted);font-size:12px;white-space:nowrap}
.up{color:var(--green)} .down{color:var(--red)}
.verdict{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.12em;padding:4px 10px;border-radius:2px;white-space:nowrap}
.verdict.FARM{background:var(--gold);color:#14100a}
.verdict.THIN{border:1px solid var(--gold);color:var(--gold)}
.verdict.SKIP{border:1px solid var(--faint);color:var(--faint)}
.footnote{color:var(--faint);font-size:12px;margin-top:10px;max-width:820px}
.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px}
@media(max-width:820px){.method-grid{grid-template-columns:1fr}h1{font-size:38px}}
.panel{background:var(--panel);border:1px solid var(--rule);padding:20px 22px}
.formula{font-size:15px;line-height:1.9;color:var(--gold);background:var(--canvas);
  border:1px solid var(--rule);padding:14px 16px}
.proof td,.proof th{padding:8px 10px}
.proof tbody tr{cursor:default}
.proof tbody tr:hover{background:none}
#chart svg{display:block;width:100%;height:auto;background:var(--canvas);border:1px solid var(--rule)}
.caption{color:var(--faint);font-size:12px;margin-top:8px}
dialog{background:var(--panel);color:var(--ink);border:1px solid var(--gold-dim);max-width:680px;width:92%;
  padding:22px 28px;box-shadow:0 24px 80px rgba(0,0,0,.7)}
dialog::backdrop{background:rgba(5,5,7,.8)}
.close{position:absolute;top:10px;right:14px;background:none;border:0;color:var(--muted);font-size:26px;cursor:pointer}
.close:hover{color:var(--ink)}
#detailBody h2{font-size:28px;padding-right:30px}
#detailBody h2 small{display:block;font-family:var(--mono);font-size:12px;color:var(--copper);text-transform:uppercase;letter-spacing:.16em;margin-bottom:6px}
.kv{display:grid;grid-template-columns:1fr 1fr;gap:6px 26px;margin:14px 0}
.kv div{border-bottom:1px solid var(--rule);padding:5px 0}
.kv dt{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.12em}
.kv dd{margin:2px 0 0;font-size:16px}
.steps{list-style:none;margin:14px 0 0;padding:0;counter-reset:step}
.steps li{counter-increment:step;position:relative;padding:0 0 10px 44px;border-left:1px solid var(--rule2);margin-left:12px}
.steps li:last-child{border-left-color:transparent}
.steps li::before{content:counter(step,decimal-leading-zero);position:absolute;left:-13px;top:0;
  background:var(--canvas);border:1px solid var(--copper);color:var(--gold);font-size:11px;
  width:25px;height:25px;line-height:24px;text-align:center;border-radius:50%}
.steps .meta{color:var(--copper);font-size:12px;margin-top:3px}
footer{border-top:3px double var(--rule2);margin-top:34px;padding-top:14px;color:var(--faint);font-size:12px}
